"""Build the D'Andrea content into the modernized industrial presentation layout."""
import json,pathlib,html,urllib.parse,re
ROOT=pathlib.Path(__file__).resolve().parents[1];DIST=ROOT/'dist'
D=json.loads((ROOT/'content/site.json').read_text(encoding='utf-8'));C=D['company'];CATS=D['categories'];PRODUCTS=D['products']
ORIGIN='https://d-andrea.vercel.app'
# ---- Central contact configuration (single source of truth for JS + templates) ----
CONTACTS={
 'br':{'lang':'pt-BR','name':'Brasil','phone':'+55 19 3671-1858','wa':'5519998575484','waMsg':'Olá! Conheci a D’Andrea pelo site e gostaria de receber mais informações sobre as soluções industriais.','waLabel':'Fale conosco pelo WhatsApp','floatAria':'Fale com a D’Andrea pelo WhatsApp'},
 'es':{'lang':'es','name':'España','phone':'+55 19 99857-5484','wa':'5519998575484','waMsg':'¡Hola! He visitado el sitio web de D’Andrea y me gustaría recibir más información sobre sus soluciones industriales.','waLabel':'Escríbenos por WhatsApp','floatAria':'Hable con D’Andrea por WhatsApp'},
 'us':{'lang':'en','name':'United States','facetime':'19547370330','phone':'+1 (954) 737-0330','floatAria':'Contact us on FaceTime'},
}
def e(s):return html.escape(str(s),quote=True)
def caturl(c):return '/solucoes/'+c['slug']+'/'
def purl(p):return '/produtos/'+p['slug']+'/'
def img(src,alt='',cls='',eager=False):return f'<img src="{e(src)}" alt="{e(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async">'
def btn(text,url,kind='primary'):return f'<a class="btn {kind}" href="{e(url)}">{text}<span aria-hidden="true">↗</span></a>'
def form(prefix='main',product=''):
 return f'''<form class="quote-form" id="{prefix}-form" novalidate><h3 data-i18n="form_title">Peça seu orçamento</h3><p data-i18n="form_sub">Conte o que a sua operação precisa.</p><div class="form-grid"><label><span>Nome completo</span><input name="name" autocomplete="name" placeholder="Nome completo*" required minlength="3"></label><label><span>Telefone</span><input type="tel" name="phone" autocomplete="tel" inputmode="tel" pattern="[+0-9 ()().-]{{8,24}}" placeholder="Telefone / WhatsApp*" required minlength="8"></label><label><span>Empresa</span><input name="company" autocomplete="organization" placeholder="Empresa*" required minlength="2"></label><label><span>E-mail</span><input type="email" name="email" autocomplete="email" placeholder="E-mail*" required></label></div><label><span>Mensagem</span><textarea name="message" data-default-product="{e(product)}" placeholder="Conte o que precisa: produto, aplicação e capacidade*" required minlength="10">{e('Gostaria de informações sobre '+product+'.' if product else '')}</textarea></label><input class="hp-field" type="text" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><label class="form-consent"><input type="checkbox" name="consent" required><span>Autorizo a abertura do WhatsApp com os dados preenchidos para que eu possa revisar e enviar o pedido à D’Andrea.</span></label><button class="btn green" type="submit" data-i18n="form_submit">Preparar mensagem <span aria-hidden="true">↗</span></button><p class="form-status" role="status" aria-live="polite" hidden></p></form>'''
FLAGS={
 'br':'<svg viewBox="0 0 20 14" aria-hidden="true"><rect width="20" height="14" fill="#009b3a"/><polygon points="10,1.5 18.4,7 10,12.5 1.6,7" fill="#fedf00"/><circle cx="10" cy="7" r="3" fill="#002776"/><rect width="20" height="14" fill="none" stroke="#ffffff33"/></svg>',
 'es':'<svg viewBox="0 0 20 14" aria-hidden="true"><rect width="20" height="14" fill="#aa151b"/><rect x="2.5" y="4" width="15" height="6" fill="#f1bf00"/></svg>',
 'us':'<svg viewBox="0 0 20 14" aria-hidden="true"><rect width="20" height="14" fill="#fff"/><g fill="#b22234"><rect y="0" width="20" height="1.1"/><rect y="2.2" width="20" height="1.1"/><rect y="4.4" width="20" height="1.1"/><rect y="6.6" width="20" height="1.1"/><rect y="8.8" width="20" height="1.1"/><rect y="11" width="20" height="1.1"/><rect y="13" width="20" height="1.1"/></g><rect width="9" height="7.7" fill="#3c3b6e"/></svg>',
}
def flags(place='top'):
 opts=''.join(f'<button type="button" class="flag-btn" data-country="{k}" aria-label="{e(v["name"])}" title="{e(v["name"])}">{FLAGS[k]}<span>{k.upper()}</span></button>' for k,v in CONTACTS.items())
 return f'<div class="lang-switch lang-switch-{place}" role="group" aria-label="Seletor de país e idioma">{opts}</div>'
def header():
 categories=''.join(f'<a href="{caturl(c)}"><span class="mega-index">0{i+1}</span><span><strong data-i18n="category_{i}">{e(c["name"])}</strong><small>{len(c["products"])} soluções</small></span><span class="mega-arrow" aria-hidden="true">↗</span></a>' for i,c in enumerate(CATS))
 nav=f'<a href="/a-empresa/" data-i18n="story">Nossa história</a><div class="nav-dropdown"><button type="button" class="nav-solutions" aria-expanded="false" aria-controls="solutions-menu" data-solutions-toggle><span data-i18n="solutions">Soluções</span><span aria-hidden="true">⌄</span></button><div class="mega-menu" id="solutions-menu" hidden><div><p class="eyebrow">Conheça as linhas D’Andrea</p><h3>Soluções para cada etapa da produção</h3></div><div class="mega-links">{categories}<a class="mega-all" href="/produtos/">Ver catálogo completo <span aria-hidden="true">↗</span></a></div></div></div>'+''.join(f'<a class="nav-category" href="{caturl(c)}" data-i18n="category_{i}">{e(c["name"])}</a>' for i,c in enumerate(CATS))+'<a href="/contato/" data-i18n="contact">Contato</a>'
 mobile_nav=f'<a href="/a-empresa/" data-i18n="story">Nossa história</a><a href="/produtos/" data-i18n="all_solutions">Todas as soluções</a>'+''.join(f'<a href="{caturl(c)}" data-i18n="category_{i}">{e(c["name"])}</a>' for i,c in enumerate(CATS))+'<a href="/contato/" data-i18n="contact">Contato</a>'
 return f'''<a class="skip" href="#main">Ir para o conteúdo</a><div class="topbar"><div class="wrap topbar-row"><span data-i18n="topbar">Máquinas e soluções industriais · Desde 1934 · Brasil e Estados Unidos</span><div class="topbar-actions"><a class="topbar-phone" data-contact-phone href="tel:+551936711858">☎ <span>+55 19 3671-1858</span></a>{flags('top')}</div></div></div><header class="site-header" data-header><div class="wrap header-row"><a class="header-brand" href="/" aria-label="D’Andrea, página inicial">{img(C['headerLogo'],'D’Andrea Company','logo',True)}</a><nav class="desktop-nav" aria-label="Navegação principal">{nav}</nav><div class="header-actions"><button class="search-toggle" type="button" aria-label="Pesquisar soluções" aria-expanded="false" aria-controls="header-search" data-search-toggle><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.5"/><path d="m16 16 4.5 4.5"/></svg></button><a class="btn catalog-btn" href="/produtos/" data-i18n="catalog">Ver catálogo</a><a class="btn primary quote-header" href="/contato/#formulario" data-i18n="quote">Pedir orçamento</a><button class="menu-toggle" aria-label="Abrir menu" aria-expanded="false" aria-controls="main-menu">☰</button></div><form class="header-search" id="header-search" role="search" hidden><label for="header-search-input" data-i18n="search_label">Buscar entre 24 soluções</label><div><input type="search" id="header-search-input" placeholder="Ex.: tubos de papel" autocomplete="off"><button class="btn primary" type="submit" data-i18n="search_button">Buscar</button></div></form></div><nav id="main-menu" class="mobile-menu wrap" aria-label="Menu completo" hidden>{flags('mobile')}{mobile_nav}<a class="btn catalog-btn" href="/produtos/" data-i18n="catalog">Ver catálogo</a><a class="btn primary" href="/contato/#formulario" data-i18n="quote">Pedir orçamento</a></nav></header>'''
def footer():
 return f'''<footer><div class="wrap footer-grid"><div><a href="/">{img(C['logo'],'D’Andrea Company','footer-logo')}</a><h3 data-i18n="footer_tagline">Seu sonho realizado</h3><p data-i18n="footer_description">Soluções para conversão de papel, embalagens, papel tissue e equipamentos complementares.</p><div class="social">{''.join(f'<a href="{v}" target="_blank" rel="noopener noreferrer">{k} ↗</a>' for k,v in C['social'].items())}</div></div><div><h4 data-i18n="solutions">Soluções</h4>{''.join(f'<a href="{caturl(c)}" data-i18n="category_{i}">{e(c["name"])}</a>' for i,c in enumerate(CATS))}</div><div><h4 data-i18n="footer_institutional">Institucional</h4><a href="/" data-i18n="footer_home">Início</a><a href="/a-empresa/" data-i18n="story">Nossa história</a><a href="/contato/" data-i18n="footer_contact">Fale conosco</a><a href="/contato/" data-i18n="footer_privacy">Informações sobre privacidade</a></div><div><h4>Brasil</h4><p>{C['brazilAddress']}</p><a href="tel:+551936711858">{C['phone']}</a><a href="tel:+5519998575484">{C['mobile'][0]}</a><a href="tel:+5519996869561">{C['mobile'][1]}</a><h4 class="mt">Estados Unidos</h4><p>{C['usAddress']}</p><a class="us-phone" href="tel:+19547370330">+1 (954) 737-0330</a></div></div><div class="wrap footer-bottom"><span>© 2026 D’Andrea Company. Todos os direitos reservados.</span><span>Inovando · Construindo · Superando, sempre</span><a href="#top">Voltar ao topo ↑</a></div></footer><div class="floating-contact" id="floating-contact"><a class="float-wa" href="https://wa.me/5519998575484" target="_blank" rel="noopener noreferrer" aria-label="Fale com a D’Andrea pelo WhatsApp"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#fff" d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2Zm5.4 14.1c-.2.7-1.3 1.3-1.9 1.4-.5.1-1.1.2-3.4-.7-2.9-1.2-4.7-4.1-4.9-4.3-.1-.2-1.1-1.5-1.1-2.9s.7-2 1-2.3c.2-.3.5-.3.7-.3h.5c.2 0 .4 0 .6.5l.9 2.1c.1.2.1.4 0 .6l-.4.6-.5.5c-.2.2-.3.4-.1.7.2.3.9 1.5 2 2.4 1.4 1.2 2.5 1.6 2.8 1.7.3.1.5.1.7-.1l1-1.2c.2-.3.4-.2.7-.1l2 1c.3.1.5.2.6.4 0 .1 0 .7-.2 1.4Z"/></svg></a><a class="float-ft" href="facetime:19547370330" aria-label="Contact us on FaceTime" hidden><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2" y="5" width="13" height="14" rx="3" fill="#fff"/><path d="M15.5 12l6-4.2v8.4Z" fill="#fff"/></svg></a><a class="float-us-info" href="tel:+19547370330" aria-label="Call the United States contact" hidden>Call +1 (954) 737-0330</a></div><dialog id="image-dialog"><button class="dialog-close" aria-label="Fechar imagem">×</button><img alt=""><p></p></dialog>'''
def layout(title,body,path,desc='Soluções D’Andrea para conversão de papel, embalagens, tissue e equipamentos complementares. Desde 1934.'):
 config=json.dumps({'contacts':CONTACTS,'format': 'localized quote request via WhatsApp prefilled message'},ensure_ascii=False)
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(desc)}"><title>{e(title)} | D’Andrea Company</title><meta property="og:type" content="website"><meta property="og:site_name" content="D’Andrea Company"><meta property="og:title" content="{e(title)} | D’Andrea Company"><meta property="og:description" content="{e(desc)}"><meta property="og:image" content="{ORIGIN}/media/bg.jpg"><meta property="og:url" content="{ORIGIN}{path}"><meta property="og:locale" content="pt_BR"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="{ORIGIN}{path}"><link rel="icon" href="/media/da-logo.png"><link rel="stylesheet" href="/assets/fonts.css"><link rel="stylesheet" href="/assets/dandrea.css?v=modern-20261104"><script>window.DANDREA={config}</script><script src="/assets/dandrea.js?v=modern-20261104" defer></script></head><body id="top">{header()}<main id="main">{body}</main>{footer()}</body></html>'''
def write(path,title,body,desc=None):
 p=DIST/path.strip('/')/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(layout(title,body,path,**({'desc':desc} if desc else {})),encoding='utf-8')
def intro(eyebrow,title,description='',image='/media/bg.jpg'):
 return f'<section class="page-hero reveal-section" style="--page-image:url(\'{image}\')"><div class="wrap"><nav class="breadcrumbs" aria-label="Você está aqui"><a href="/">Início</a><span>/</span><span>{e(eyebrow)}</span></nav><p class="eyebrow light">{e(eyebrow)}</p><h1>{e(title)}</h1><p>{e(description)}</p></div></section>'
def card(p):
 cat=next(c for c in CATS if c['slug']==p['category'])
 return f'<article class="product-card reveal" data-category="{cat["slug"]}" data-search="{e(p["name"]+" "+p["description"])}"><a href="{purl(p)}"><span class="card-media">{img(p["image"],p["name"])}</span><div class="card-copy"><span class="eyebrow">{e(cat["short"])}</span><h3>{e(p["name"])}</h3><p>{e(p["description"])}</p><strong>Ver detalhes <span>↗</span></strong></div></a></article>'
def cards(items,carousel=False):
 inner=''.join(card(p) for p in items)
 if carousel:
  return f'<div class="carousel" data-carousel><div class="carousel-track" tabindex="0" aria-label="Carrossel de soluções">{inner}</div><button class="carousel-btn prev" type="button" aria-label="Solução anterior">←</button><button class="carousel-btn next" type="button" aria-label="Próxima solução">→</button></div>'
 return '<div class="product-grid">'+''.join(card(p) for p in items)+'</div>'
def categories():
 return '<div class="category-grid">'+''.join(f'<a class="category-card reveal" href="{caturl(c)}">{img(c["image"],c["name"])}<div><span class="eyebrow">0{i+1} · {len(c["products"])} soluções</span><h3>{e(c["name"])}</h3><span class="arrow">↗</span></div></a>' for i,c in enumerate(CATS))+'</div>'
def contact(product=''):
 return f'''<section class="section contact-section" id="formulario"><div class="wrap contact-grid"><div><p class="eyebrow">Fale com a D’Andrea</p><h2>Onde quer que você esteja,<br>estamos aqui para servi-lo.</h2><p class="lead">Entre em contato com nossa equipe e conte sobre a sua operação.</p><div class="address"><span class="country">🇧🇷</span><div><h3>Brasil</h3><p>{C['brazilAddress']}</p><a href="tel:+551936711858">{C['phone']}</a><a href="tel:+5519998575484">{C['mobile'][0]}</a><a href="tel:+5519996869561">{C['mobile'][1]}</a><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=Av.+Peri+Igel+1040+Casa+Branca+SP" target="_blank" rel="noopener noreferrer">Ver localização ↗</a></div></div><div class="address"><span class="country">🇺🇸</span><div><h3>Estados Unidos</h3><p>{C['usAddress']}</p><a class="us-phone" href="tel:+19547370330">+1 (954) 737-0330</a><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=305+Maltbie+Industrial+Dr+Lawrenceville+GA+30046" target="_blank" rel="noopener noreferrer">Ver localização ↗</a></div></div></div>{form('contact',product)}</div></section>'''
def cta():return '<section class="cta reveal-section"><div class="wrap"><div><p class="eyebrow light">Sua próxima solução</p><h2>Vamos conversar sobre a sua produção?</h2></div>'+btn('Falar com a equipe','/contato/','white')+'</div></section>'
def hero_words():
 return '<span class="hero-line"><span class="hero-word">90+ ANOS</span></span><span class="hero-line"><span class="hero-word">DE TECNOLOGIA</span></span><span class="hero-line"><span data-hero-prefix>para</span> <span class="hero-word hero-dynamic" data-hero-dynamic>CONVERSÃO DE PAPEL</span></span>'
def home():
 feature=[]
 featured_slugs=['linhas-de-producao-de-tubos-de-papel','latas-compostas','rebobinadeira-de-tissue','freios-pneumaticos']
 for i,slug in enumerate(featured_slugs):
  p=next(p for p in PRODUCTS if p['slug']==slug)
  c=next(c for c in CATS if c['slug']==p['category'])
  feature.append(f'<div class="featured-panel reveal-section" id="feature-{i}" role="tabpanel" aria-labelledby="feature-tab-{i}" {"hidden" if i else ""}><div><p class="eyebrow">{e(c["name"])}</p><h2>{e(p["name"])}</h2><p class="lead">{e(p["description"])}</p><div class="actions">{btn("Pedir orçamento","/contato/?produto="+urllib.parse.quote(p["name"])+"#formulario")}{btn("Ver detalhes",purl(p),"outline")}</div></div><a class="feature-image" href="{purl(p)}">{img(p["image"],p["name"])}</a></div>')
 historyintro=next(x['text'] for x in D['history'] if x['type']=='text')
 quote=[x for x in D['history'] if x['type']=='text'][-1]
 stats='<div class="stats-band"><div class="wrap stats-grid">'+ ''.join(f'<div class="stat"><strong data-count="{v}" data-suffix="{s}">0</strong><span>{e(l)}</span></div>' for v,s,l in [('1934','','Fundação em Limeira/SP'),('100','+','Países com máquinas D’Andrea'),('4','','Linhas de soluções'),('24','','Soluções no catálogo')])+'</div></div>'
 marquee_words=['INOVANDO','CONSTRUINDO','SUPERANDO','TECNOLOGIA INDUSTRIAL','DESDE 1934']
 track=''.join(f'<span>{e(w)}</span><b aria-hidden="true">✦</b>' for w in marquee_words)
 marquee=f'<div class="marquee" aria-hidden="true"><div class="marquee-track">{track}{track}{track}{track}</div></div>'
 return f'''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><p class="red-label">D’Andrea Company · Desde 1934</p><h1 class="hero-title">{hero_words()}</h1><p class="hero-subtitle">Inovando · Construindo · Superando, sempre</p><div class="red-rule"></div><p class="lead">Mais de 90 anos impulsionando a indústria: máquinas e soluções para conversão de papel, embalagens, papel tissue e equipamentos complementares.</p>{btn('Conhecer todas as soluções','/produtos/','white')}<a class="hero-secondary" href="#linhas">Qual é a sua aplicação? Conheça nossas linhas →</a><div class="hero-stats"><div><strong>1934</strong><span>Fundação</span></div><div><strong>100+</strong><span>Países com máquinas D’Andrea</span></div><div><strong>24</strong><span>Soluções no catálogo</span></div></div></div>{form('hero')}</div></section>{marquee}<section class="section featured"><div class="wrap">{''.join(feature)}<div class="feature-controls"><button class="feature-nav" type="button" data-feature-prev aria-label="Linha anterior">←</button><div class="feature-tabs" role="tablist" aria-label="Linhas de soluções">{''.join(f'<button type="button" id="feature-tab-{i}" role="tab" aria-selected="{str(i==0).lower()}" aria-controls="feature-{i}" data-feature="{i}"><span>0{i+1}</span>{e(c["name"])}</button>' for i,c in enumerate(CATS))}</div><button class="feature-nav" type="button" data-feature-next aria-label="Próxima linha">→</button></div></div></section>{stats}<section class="section soft"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Nossas soluções</p><h2>Tecnologia para cada etapa<br>da sua produção</h2><p>Conheça as soluções D’Andrea para a indústria de papel e embalagens.</p></div>{btn('Ver as 24 soluções','/produtos/','outline')}</div>{cards([PRODUCTS[i] for i in [0,1,3,6,9,10,17,23]],carousel=True)}</div></section><section class="section" id="linhas"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Linhas de soluções</p><h2>Do papel ao produto acabado</h2></div></div>{categories()}</div></section><section class="section history-summary"><div class="wrap split"><a class="history-photo reveal" href="/a-empresa/">{img('/media/familia_dandrea.png','Família D’Andrea')}<span>Conheça nossa história ↗</span></a><div class="reveal"><p class="eyebrow">Quem é a D’Andrea</p><h2>Uma história que começou em 1934.<br>Um legado que segue em movimento.</h2><p class="lead">{e(historyintro)}</p><div class="small-stats"><div><strong>1934</strong><span>Fundação em Limeira/SP</span></div><div><strong>100+</strong><span>Países atendidos ao longo da história</span></div></div>{btn('Nossa história','/a-empresa/')}</div></div></section><section class="brand-banner reveal-section" style="--banner:url('/media/atlanta-unsplash-e1717897039287.jpg')"><div class="wrap"><p class="eyebrow light">D’Andrea Company</p><h2>Onde quer que você esteja,<br>estamos aqui para servi-lo.</h2>{btn('Entre em contato','/contato/','white')}</div></section><section class="section"><div class="wrap"><p class="eyebrow">Presença e compromisso</p><div class="values-grid"><div class="value-image reveal">{img('/media/eagle-constitution-flag-e1717897104821.jpg','Símbolos dos Estados Unidos')}<h2>Comprometidos com<br>os valores americanos</h2></div><div class="value-image reveal">{img('/media/bg.jpg','Máquinas D’Andrea')}<h2>Inovando. Construindo.<br>Superando, sempre.</h2></div></div></div></section><section class="section quote-section"><div class="wrap quote-grid"><img class="reveal" src="/media/sergio.jpg" alt="Sergio D’Andrea" loading="lazy" decoding="async"><div class="reveal"><p class="eyebrow">Um compromisso com o futuro</p><blockquote>{''.join('<p>'+e(p)+'</p>' for p in (quote['paragraphs'] or [quote['text']]))}</blockquote></div></div></section>{contact()}'''
def catalog(category=None):
 title=category['name'] if category else 'Equipamentos para transformar papel em possibilidades'
 items=[p for p in PRODUCTS if not category or p['category']==category['slug']]
 head=intro(category['name'] if category else 'Catálogo de soluções',title,'Tecnologia D’Andrea para a sua operação. Explore os equipamentos e encontre sua solução.')
 filterbar='<div class="catalog-controls"><div class="filter-buttons" role="group" aria-label="Filtrar soluções"><button class="active" data-filter="all" aria-pressed="true">Todas <small>24</small></button>'+''.join(f'<button data-filter="{c["slug"]}" aria-pressed="false">{e(c["short"])} <small>{len(c["products"])}</small></button>' for c in CATS)+'</div><label class="search-label"><span>Buscar soluções</span><input type="search" id="catalog-search" placeholder="Buscar no catálogo…" autocomplete="off"></label></div>' if not category else '<label class="search-label category-search"><span>Buscar nesta linha</span><input type="search" id="catalog-search" placeholder="Buscar nesta linha…" autocomplete="off"></label>'
 return head+f'<section class="section"><div class="wrap" id="catalog">{filterbar}<p id="result-count" role="status" aria-live="polite">{len(items)} soluções</p>{cards(items)}<div id="empty-state" hidden><h2>Nenhuma solução encontrada</h2><p>Tente outro termo ou selecione outra linha.</p><button class="btn outline" id="clear-filters">Limpar busca</button></div></div></section>'+cta()
def product(p):
 cat=next(c for c in CATS if c['slug']==p['category'])
 return f'''<section class="section product-detail"><div class="wrap"><nav class="breadcrumbs dark" aria-label="Você está aqui"><a href="/">Início</a><span>/</span><a href="/produtos/">Soluções</a><span>/</span><a href="{caturl(cat)}">{e(cat['name'])}</a></nav><div class="split product-overview"><button class="gallery-image reveal" data-zoom="{p['image']}" data-caption="{e(p['name'])}" aria-label="Ampliar imagem de {e(p['name'])}">{img(p['image'],p['name'],'',True)}<span>Ampliar imagem ⊕</span></button><div class="reveal"><p class="eyebrow">{e(cat['name'])}</p><h1>{e(p['name'])}</h1>{''.join('<p class="lead">'+e(t)+'</p>' for t in p['paragraphs'])}<div class="actions">{btn('Pedir orçamento','/contato/?produto='+urllib.parse.quote(p['name'])+'#formulario')}{btn('Assista aos vídeos',C['social']['YouTube'],'outline')}</div><a class="phone-link" href="tel:+551936711858">☎ {C['phone']}</a></div></div></div></section><section class="section soft"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Explore a linha</p><h2>Outras soluções em {e(cat['short'].lower())}</h2></div>{btn('Ver linha completa',caturl(cat),'outline')}</div>{cards([x for x in PRODUCTS if x['category']==p['category'] and x['slug']!=p['slug']][:3])}</div></section>{contact(p['name'])}'''
def history():
 """Build an animated timeline from the registered history content, preserving every fact, paragraph and image."""
 items=[];intro_nodes=[];cur=None;quote=None
 for n in D['history']:
  t=n['type']
  if t=='heading':
   m=re.match(r'^(\d{4})\b[\s\-–—:]*(.*)$',n['text'].strip())
   if m and 1900<int(m.group(1))<2100:
    cur={'year':m.group(1),'title':m.group(2).strip(),'paras':[],'images':[]};items.append(cur);continue
   if cur is None:intro_nodes.append(n)
   elif not cur['title']:cur['title']=n['text']
   else:cur.setdefault('extra',[]).append(n['text'])
  elif t=='text':
   if cur is None:intro_nodes.append(n)
   elif items and items[-1] is cur and len(cur['paras'])==0 and cur is items[-1]:cur['paras'].extend(n['paragraphs'] or [n['text']])
   else:quote=n
  else:
   if cur is None:intro_nodes.append(n)
   else:cur['images'].extend(n['images'])
 # closing quote = last standalone text after the final era
 if quote is None:
  quote={'paragraphs':None,'text':''}
 intro_html=[]
 for n in intro_nodes:
  if n['type']=='heading':
   if '100 anos' in n['text'] or 'quase 100 anos' in n['text']:continue
   intro_html.append('<h2>'+e(n['text'])+'</h2>')
  elif n['type']=='text':intro_html.append(''.join('<p>'+e(p)+'</p>' for p in (n['paragraphs'] or [n['text']])))
  else:intro_html.append(''.join('<figure>'+img(u,'Arquivo histórico D’Andrea')+'</figure>' for u in n['images']))
 tl=''.join(f'''<li class="tl-item {'tl-alt' if i%2 else ''} reveal"><div class="tl-marker"><span></span></div><div class="tl-card"><span class="tl-year">{e(it['year'])}</span>{f'<h3>{e(it["title"])}</h3>' if it['title'] else ''}{''.join('<p>'+e(x)+'</p>' for x in it.get('extra',[]))}{''.join('<p>'+e(p)+'</p>' for p in it['paras'])}{''.join('<figure>'+img(u,'Arquivo histórico D’Andrea')+'</figure>' for u in it['images'])}</div></li>''' for i,it in enumerate(items))
 quote_html=''.join('<p>'+e(p)+'</p>' for p in (quote.get('paragraphs') or [quote.get('text','') if quote.get('text') else ''])) if (quote.get('paragraphs') or quote.get('text')) else ''
 return intro('Nossa história','Mais de 90 anos de história D’Andrea','Da iniciativa de uma família em 1934 à tecnologia presente em mais de 100 países.')+'<section class="section"><div class="wrap history-layout"><aside class="history-aside"><p class="eyebrow">Nossa trajetória</p><strong>Desde<br>1934</strong><p>Pioneirismo, coragem e tecnologia a serviço da indústria.</p>'+btn('Conhecer soluções','/produtos/','outline')+'</aside><article class="history-article"><div class="history-intro">'+''.join(intro_html)+'</div><ol class="timeline" aria-label="Linha do tempo da história D’Andrea">'+tl+'</ol>'+(f'<blockquote class="history-quote reveal">{quote_html}</blockquote>' if quote_html else '')+'</article></div></section>'+cta()
write('/','Máquinas para Conversão de Papel, Embalagens e Papel Tissue',home(),'Fabricantes de máquinas para conversão de papel, embalagens, papel tissue e equipamentos complementares desde 1934. Máquinas D’Andrea presentes em mais de 100 países.')
write('/produtos/','Catálogo de soluções industriais',catalog(),'Catálogo com 24 soluções D’Andrea: máquinas para conversão de papel, embalagens, papel tissue e equipamentos complementares para a sua operação.')
for c in CATS:
 write(caturl(c),c['name'],catalog(c))
 write('/'+c['sourcePath']+'/',c['name'],catalog(c))
for p in PRODUCTS:write(purl(p),p['name'],product(p),p['description'])
write('/a-empresa/','Nossa história desde 1934',history(),'A trajetória da D’Andrea: de uma família italiana em Limeira, em 1934, a máquinas presentes em mais de 100 países.');write('/history/','Nossa história desde 1934',history())
for route in ['/contato/','/contact-us/','/contact/']:write(route,'Contato e orçamentos',intro('Contato','Vamos conversar sobre a sua produção','D’Andrea Company · Brasil e Estados Unidos')+contact(),'Fale com a D’Andrea Company: telefone, WhatsApp e orçamentos de máquinas para conversão de papel, embalagens e tissue.')
(DIST/'404.html').write_text(layout('Página não encontrada',intro('Página não encontrada','Vamos encontrar a solução que você procura.')+'<section class="section"><div class="wrap">'+btn('Ver todas as soluções','/produtos/')+'</div></section>','/404.html','Página não encontrada.'),encoding='utf-8')
(DIST/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n',encoding='utf-8')
# ---- SEO: sitemap + robots ----
routes=['/']+[purl(p) for p in PRODUCTS]+[caturl(c) for c in CATS]+['/'+c['sourcePath']+'/' for c in CATS]+['/produtos/','/a-empresa/','/history/','/contato/','/contact-us/','/contact/']
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{r}</loc></url>' for r in routes)+'</urlset>',encoding='utf-8')
(DIST/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}/sitemap.xml\n',encoding='utf-8')
print('Built',len(list(DIST.rglob('index.html'))),'pages; all',len(PRODUCTS),'source products included.')
